#[cfg(test)]
mod tests {
    use super::*;

    fn rep(a: &str, b: &str) -> Box<dyn Transform> {
        Box::new(Replace { from: a.to_string(), to: b.to_string() })
    }

    #[test]
    fn individual() {
        assert_eq!(Upper.apply("abc"), "ABC");
        assert_eq!(Reverse.apply("abc"), "cba");
        assert_eq!(Truncate(2).apply("hello"), "he");
        assert_eq!(Truncate(10).apply("hi"), "hi");
    }

    #[test]
    fn unicode_safe() {
        assert_eq!(Reverse.apply("héllo"), "olléh");
        assert_eq!(Truncate(2).apply("日本語"), "日本");
    }

    #[test]
    fn pipeline() {
        let steps: Vec<Box<dyn Transform>> = vec![rep("cat", "dog"), Box::new(Upper), Box::new(Reverse)];
        assert_eq!(run_pipeline(&steps, "my cat"), "GOD YM");
    }

    #[test]
    fn empty_pipeline() {
        assert_eq!(run_pipeline(&[], "unchanged"), "unchanged");
    }

    #[test]
    fn order_matters() {
        let a: Vec<Box<dyn Transform>> = vec![Box::new(Truncate(3)), Box::new(Reverse)];
        let b: Vec<Box<dyn Transform>> = vec![Box::new(Reverse), Box::new(Truncate(3))];
        assert_eq!(run_pipeline(&a, "abcdef"), "cba");
        assert_eq!(run_pipeline(&b, "abcdef"), "fed");
    }
}
